<script setup lang="ts">
const route = useRoute(); const groupId = String(route.params.id)
const {data, error: fetchError, refresh} = await useFetch<any>(`/api/groups/${groupId}`)
const tab = ref('decisions'); const filter = ref('All'); const search = ref(''); const creating = ref(false); const token = ref(''); const error = ref(''); const notice = ref(''); const savedKey = ref('')
const items = computed(() => (data.value?.proposals || []).filter((p:any) => (filter.value === 'All' || (filter.value === 'In review' ? p.status === 'Review' : p.status !== 'Review')) && `${p.title} ${p.program}`.toLowerCase().includes(search.value.toLowerCase())).sort((a:any,b:any) => b.createdAt.localeCompare(a.createdAt)))
onMounted(() => { savedKey.value = sessionStorage.getItem(`organizer_${groupId}`) || '' })
function dismissKey() { savedKey.value=''; sessionStorage.removeItem(`organizer_${groupId}`) }
async function claim() { error.value=''; try { await $fetch(`/api/groups/${groupId}/claim`, {method:'POST',body:{token:token.value}}); token.value=''; await refresh() } catch(e:any) { error.value=e.data?.statusMessage || 'Could not restore access.' } }
async function copy() { try { await navigator.clipboard.writeText(location.href); notice.value='Group link copied.' } catch { notice.value='Copy the group URL from your address bar.' } }
function date(s:string) { return new Date(s).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}) }
</script>
<template><UnlockGate v-if="data?.locked" :endpoint="`/api/groups/${groupId}/unlock`" label="group" @unlocked="refresh" /><main v-else-if="data?.group" class="workspace"><NuxtLink to="/" class="breadcrumb">← Home</NuxtLink><div class="workspace-head"><div><div class="eyebrow">GROUP</div><h1 class="medium">{{ data.group.name }}</h1><p v-if="data.group.description">{{ data.group.description }}</p></div><div class="actions"><button class="button secondary" @click="copy">↗ Share group</button><button v-if="data.isAdmin" class="button" @click="creating = !creating">＋ New proposal</button></div></div><p v-if="notice" class="notice" role="status">{{ notice }}</p><section v-if="savedKey" class="notice key-note"><strong>Save your organizer key.</strong> It lets you manage this group on another browser. Treat it like a password.<code>{{ savedKey }}</code><button class="subtle" @click="dismissKey()">I’ve saved it · dismiss</button></section><ProposalForm v-if="creating" :group-id="groupId" @cancel="creating=false" @created="(p:any) => navigateTo(`/d/${p.id}`)" /><template v-else><div class="stats"><div><span>{{ data.proposals.length }}</span>proposals</div><div><span>{{ data.proposals.filter((p:any)=>p.status==='Review').length }}</span>in review</div><div><span>{{ data.proposals.filter((p:any)=>p.status==='Agreed').length }}</span>agreed</div></div><nav class="tabs" aria-label="Group views"><button :class="{active:tab==='decisions'}" @click="tab='decisions'">Decisions <span>{{ data.proposals.length }}</span></button><button :class="{active:tab==='timeline'}" @click="tab='timeline'">Group timeline</button></nav><template v-if="tab==='decisions'"><div class="toolbar"><div class="filters"><button v-for="f in ['All','In review','Past decisions']" :key="f" :class="{selected:filter===f}" @click="filter=f">{{ f }}</button></div><input v-model="search" class="search" type="search" aria-label="Search decisions" placeholder="Search decisions…"></div><div v-if="items.length" class="decision-list"><NuxtLink v-for="p in items" :key="p.id" :to="`/d/${p.id}`" class="decision-row"><div class="decision-icon">{{ p.type==='Policy change' ? '§' : p.type==='Event' ? '✳' : '↗' }}</div><div class="decision-info"><div class="row-meta"><span>{{ p.program || p.type }}</span><span v-if="p.locked">Password protected</span></div><h3>{{ p.title }}</h3><p>{{ p.facilitator }} · {{ date(p.createdAt) }} · Revision {{ p.revision }}</p></div><div class="row-end"><span class="badge" :class="p.status==='Agreed'?'agreed':p.status==='Review'?'review':''">{{ p.status==='Review' && Date.now() >= Date.parse(p.deadline) ? 'Awaiting outcome' : p.status==='Review' ? 'In review' : p.status }}</span><small>{{ p.status==='Review' ? 'Review ends ' + date(p.deadline) : p.outcome.slice(0,70) }}</small></div><span class="arrow">↗</span></NuxtLink></div><section v-else class="empty"><h2>{{ search || filter!=='All' ? 'No matching decisions' : 'No proposals yet' }}</h2><p>{{ data.isAdmin ? search || filter!=="All" ? 'Try another search or filter.' : 'Create a proposal to begin review.' : 'The facilitator can create a proposal for review.' }}</p><button v-if="data.isAdmin && !search && filter==='All'" class="button" @click="creating=true">Create proposal</button></section></template><section v-else class="panel timeline"><h2>Group activity</h2><div v-for="a in data.activity" :key="a.id" class="event"><span class="event-dot"/><div><time>{{ date(a.createdAt) }}</time><p>{{ a.text }}</p><NuxtLink v-if="a.proposalId" :to="`/d/${a.proposalId}`">View decision ↗</NuxtLink></div></div></section></template><details v-if="!data.isAdmin" class="restore"><summary>Facilitator? Restore organizer access.</summary><form @submit.prevent="claim"><label>Organizer key<input v-model="token" type="password" required autocomplete="off"></label><p v-if="error" class="error">{{ error }}</p><button class="button">Restore access</button></form></details></main><main v-else class="narrow"><h1 class="medium">{{ fetchError?.statusCode===404 ? 'Group not found.' : 'Could not load this group.' }}</h1><p>Check your link and try again.</p><button class="button" @click="refresh()">Try again</button></main></template>
